//! ↩️ create-animation leaf-owned inverse reconstruction from exact base values.
use serde::{Deserialize, Serialize};
use crate::artifacts::gltf::GltfSnapshot;
use crate::artifacts::gltf::schema::snapshot::GltfAnimation;
use crate::artifacts::gltf::schema::mutations::create_animation::mutation::{validate, GltfCreateAnimationPayload};
use crate::artifacts::gltf::schema::mutations::top_level_collections_private::{animations_op, reject, repair, Change, GltfTopLevelFamily, GltfTopLevelMutationRejection};
pub const ID: &str = "s.stdio.gltf.mutation.create-animation.v1.inverse";
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(tag = "kind", rename_all = "camelCase")]
pub enum GltfCreateAnimationInverseOperation { Insert { position: usize, item: GltfAnimation }, Delete { index: usize, removed: GltfAnimation }, Move { index: usize, position: usize }, Reorder { order: Vec<usize> } }
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(rename_all = "camelCase")]
pub struct GltfCreateAnimationInverse { pub id: String, pub version: u32, pub touched_paths: Vec<String>, pub payload: GltfCreateAnimationPayload, pub operation: GltfCreateAnimationInverseOperation }
fn operation(payload: &GltfCreateAnimationPayload, base: &GltfSnapshot) -> GltfCreateAnimationInverseOperation { GltfCreateAnimationInverseOperation::Delete { index: payload.position, removed: GltfAnimation::default() } }
fn touched_paths(payload: &GltfCreateAnimationPayload) -> Vec<String> { vec![format!("document/animations/{}", payload.position)] }
pub fn validate_inverse(inverse: &GltfCreateAnimationInverse) -> Result<(), GltfTopLevelMutationRejection> { if inverse.id != ID || inverse.version != 1 { return Err(reject("gltf.mutation.invalid-inverse-envelope", "inverse", "descriptor identity does not match")); } if inverse.touched_paths != touched_paths(&inverse.payload) { return Err(reject("gltf.mutation.invalid-touched-paths", "inverse/touchedPaths", "paths must be concrete payload-derived locations")); } Ok(()) }
pub fn apply_inverse(inverse: &GltfCreateAnimationInverse, after: &GltfSnapshot) -> Result<GltfSnapshot, GltfTopLevelMutationRejection> { validate_inverse(inverse)?; let operation = &inverse.operation; match operation { GltfCreateAnimationInverseOperation::Insert { position, .. } if *position > after.document.animations.len() => return Err(reject("gltf.mutation.insert-out-of-range", "document/animations", "position must be within the collection")), GltfCreateAnimationInverseOperation::Delete { index, .. } if *index >= after.document.animations.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/animations", "index must address an item")), GltfCreateAnimationInverseOperation::Move { index, position } if *index >= after.document.animations.len() || *position >= after.document.animations.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/animations", "indices must address items")), GltfCreateAnimationInverseOperation::Reorder { order } if order.is_empty() || order.len() != after.document.animations.len() || order.iter().collect::<std::collections::BTreeSet<_>>().len() != order.len() || order.iter().any(|index| *index >= after.document.animations.len()) => return Err(reject("gltf.mutation.invalid-permutation", "document/animations", "order must be a non-empty permutation")), _ => {} } let mut next = after.clone(); match operation { GltfCreateAnimationInverseOperation::Insert { position, item } => { repair(&mut next.document, GltfTopLevelFamily::Animations, &Change::Insert(*position))?; next.document.animations.insert(*position, item.clone());  }, GltfCreateAnimationInverseOperation::Delete { index, .. } => { animations_op(&mut next, GltfTopLevelFamily::Animations, *index, None, None)?;  }, GltfCreateAnimationInverseOperation::Move { index, position } => { animations_op(&mut next, GltfTopLevelFamily::Animations, *index, Some(*position), None)?;  }, GltfCreateAnimationInverseOperation::Reorder { order } => { animations_op(&mut next, GltfTopLevelFamily::Animations, order[0], None, Some(order))?;  } } Ok(next) }
pub fn encode(inverse: &GltfCreateAnimationInverse) -> Result<Vec<u8>, GltfTopLevelMutationRejection> { serde_json::to_vec(inverse).map_err(|error| reject("gltf.mutation.encode-failed", "inverse", error.to_string())) }
pub fn derive(payload: &GltfCreateAnimationPayload, base: &GltfSnapshot) -> Result<GltfCreateAnimationInverse, GltfTopLevelMutationRejection> { validate(payload, base)?; Ok(GltfCreateAnimationInverse { id: ID.into(), version: 1, touched_paths: touched_paths(payload), payload: payload.clone(), operation: operation(payload, base) }) }
